style.css:
@-moz-document domain("roblox.com") {
/* https://r2.erweima.ai/i/Gw2NWgoXcAAPGgT.jfif */
    body {
        background-image: url("https://r2.erweima.ai/i/Gw2NWgoXcAAPGgT.jfif") !important;
        background-attachment: fixed !important;
        background-size: cover !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
        background-color: #1a1b26 !important;
    }

    /* Tornar o fundo das páginas transparente */
    .content, .container-main, .gui-container, #container-main {
        background: rgba(26, 27, 38, 0.6) !important;
        backdrop-filter: blur(10px) !important;
        border-radius: 15px !important;
    }

    /* Barra Superior (Top Bar) */
    #header {
        background: rgba(99, 119, 184, 0.8) !important; /* Cor azulada do seu código */
        backdrop-filter: blur(5px) !important;
    }

    /* Cards de Jogos e Itens */
    .game-card-container, .item-card-container, .m-item-card {
        background: rgba(203, 224, 247, 0.1) !important;
        border: 1px solid rgba(203, 224, 247, 0.2) !important;
        border-radius: 10px !important;
        transition: transform 0.2s ease;
    }

    .game-card-container:hover {
        transform: scale(1.05);
        background: rgba(203, 224, 247, 0.2) !important;
    }

    /* Textos e Links */
    .text-name, .text-card-title, .text-title, h1, h2 {
        color: #cbe0f7 !important;
        text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.8) !important;
    }

    a, .text-link {
        color: #d1b3ff !important;
    }

    /* Botões */
    .btn-common-play-large, .btn-primary-md {
        background-color: #6377b8 !important;
        border: none !important;
        box-shadow: 0 0 10px rgba(99, 119, 184, 0.5) !important;
    }
}
